/// <summary>
/// The <c>METSalesOrderLoadPlanningAidController</c> class is the helper class for the associated SRS Report.
/// </summary>
class METSalesOrderLoadPlanningAidController extends SrsReportRunController
{
    METSalesOrderLoadPlanningAidContract salesLoadPlanningAidContract;
}

Method.Source:
public static METSalesOrderLoadPlanningAidController construct()
{
    return new METSalesOrderLoadPlanningAidController();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    METSalesOrderLoadPlanningAidController controller = METSalesOrderLoadPlanningAidController::construct();

    controller.parmReportName(ssrsReportStr(METSalesLoadPlanningAidReport, Report));
    controller.parmArgs(_args);
    controller.parmShowDialog(false);

    METSalesOrderLoadPlanningAidContract salesLoadPlanningAidContract = controller.parmReportContract().parmRdpContract() as METSalesOrderLoadPlanningAidContract;
    METOrderExtractScreenParameters metOrderExtractScreenParameters = _args.parmObject();

    if (metOrderExtractScreenParameters && salesLoadPlanningAidContract)
    {
        str selectedExtratedOrders = _args.parm();
        if (strLen(selectedExtratedOrders) > 0)
        {
            salesLoadPlanningAidContract.parmSelectedRecords(selectedExtratedOrders);
        }
        else
        {
            salesLoadPlanningAidContract.parmSelectedRecords('');
        }
        salesLoadPlanningAidContract.parmConfirmedShipDateFrom(metOrderExtractScreenParameters.parmShippingDateConfirmFrom());
        salesLoadPlanningAidContract.parmConfirmedShipDateTo(metOrderExtractScreenParameters.parmShippingDateConfirmTo());
        salesLoadPlanningAidContract.parmCustAccount(metOrderExtractScreenParameters.parmCustAccount());
        salesLoadPlanningAidContract.parmRouteID(metOrderExtractScreenParameters.parmRoute());
        salesLoadPlanningAidContract.parmWareHouseId(metOrderExtractScreenParameters.parmWarehouse());
        salesLoadPlanningAidContract.parmInventSiteId(metOrderExtractScreenParameters.parmSite());
        salesLoadPlanningAidContract.parmExtractStatus(metOrderExtractScreenParameters.parmExtracted());
        salesLoadPlanningAidContract.parmOrderSplitGroup(metOrderExtractScreenParameters.parmOrderSplitGroup());
        salesLoadPlanningAidContract.parmSalesOrderTypeID(metOrderExtractScreenParameters.parmOrderType());
        salesLoadPlanningAidContract.parmExclCreditMgmt(metOrderExtractScreenParameters.parmCredManagement());
    }
    controller.startOperation();
}

/// <summary>
/// Loads from saved last value.
/// </summary>
protected void loadFromSysLastValue()
{
    //Do not load ranges and filters because they are always created from scratch.
    return;
}
